package com.cowave.search.controller

import com.cowave.search.controller.dto.CompileResult
import com.cowave.search.controller.dto.CreateDictionaryRequest
import com.cowave.search.controller.dto.UpdateDictionaryRequest
import com.cowave.search.domain.DictionaryWithId
import com.cowave.search.domain.Type
import com.cowave.search.service.DictionaryService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/api/v1/dictionary")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    @GetMapping("/{type}")
    fun getByType(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "0") page: Int,
        @RequestParam(defaultValue = "20") size: Int,
    ): List<DictionaryWithId> = dictionaryService.getByType(type, page, size)

    @GetMapping("/{type}/search")
    fun search(
        @PathVariable type: Type,
        @RequestParam word: String,
        @RequestParam(defaultValue = "true") isMatch: Boolean,
    ): List<DictionaryWithId> = dictionaryService.searchByWord(word, type, isMatch)

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @PathVariable id: String,
    ) {
        dictionaryService.delete(id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(type)

    @PostMapping("/compile")
    fun compileAll(): List<CompileResult> = dictionaryService.compileAll()
}

