package com.cowave.search.config

import org.springframework.boot.context.properties.ConfigurationProperties
import org.springframework.context.annotation.Configuration

@Configuration
@ConfigurationProperties(prefix = "dictionary")
class DictionaryConfig {
    var outputPath: String = "/data/dictionary"
}

package com.cowave.search.infrastructure

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.elasticsearch._types.FieldValue
import co.elastic.clients.elasticsearch._types.SortOptions
import co.elastic.clients.elasticsearch._types.SortOrder
import co.elastic.clients.elasticsearch._types.query_dsl.Query
import com.cowave.search.domain.Dictionary
import com.cowave.search.domain.DictionaryWithId
import com.cowave.search.domain.Type
import com.cowave.search.service.DictionaryRepository
import org.springframework.stereotype.Repository
import java.time.Instant

@Repository
class DictionaryRepositoryImpl(
    val esClient: ElasticsearchClient,
) : DictionaryRepository {
    override fun findAllWithPageByType(
        type: Type,
        page: Int,
        size: Int,
    ): List<DictionaryWithId> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .query { q ->
                            q.bool { b ->
                                b.filter { f ->
                                    f.term { t ->
                                        t
                                            .field("type")
                                            .value { v -> v.stringValue(type.toString()) }
                                    }
                                }
                            }
                        }.from(page)
                        .size(size)
                        .sort(baseSortQuery())
                },
                Dictionary::class.java,
            )

        return response.hits().hits().mapNotNull { hit ->
            hit.id()?.let { id -> hit.source()?.let { DictionaryWithId(id, it) } }
        }
    }

    override fun findByWordAndType(
        word: String,
        type: Type,
        isMatch: Boolean,
    ): List<DictionaryWithId> {
        val shouldQuery =
            if (isMatch) {
                Query.of {
                    it.match { m ->
                        m.field("keyword")
                        m.query { q ->
                            q.stringValue(word)
                        }
                    }
                    it.match { m2 ->
                        m2.field("value")
                        m2.query { q2 ->
                            q2.stringValue(word)
                        }
                    }
                }
            } else {
                Query.of {
                    it.wildcard { w ->
                        w.field("keyword")
                        w.value("*$word*")
                    }
                    it.wildcard { w2 ->
                        w2.field("value")
                        w2.value("*$word*")
                    }
                }
            }

        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .query { q ->
                            q.bool { b ->
                                b.filter { f ->
                                    f.term { t ->
                                        t
                                            .field("type")
                                            .value { v -> v.stringValue(type.toString()) }
                                    }
                                }
                                b.should(shouldQuery)
                            }
                        }.sort(baseSortQuery())
                },
                Dictionary::class.java,
            )

        return response.hits().hits().mapNotNull { hit ->
            hit.id()?.let { id -> hit.source()?.let { DictionaryWithId(id, it) } }
        }
    }

    override fun findAllByType(type: Type): List<Dictionary> {
        val allResults = mutableListOf<Dictionary>()
        var searchAfter: List<FieldValue>? = null
        val batchSize = 10000

        do {
            val response =
                esClient.search(
                    { s ->
                        s
                            .index(DICTIONARY_INDEX)
                            .query { q ->
                                q.term { t ->
                                    t
                                        .field("type")
                                        .value { v -> v.stringValue(type.toString()) }
                                }
                            }.size(batchSize)
                            .sort { so ->
                                so.field { f ->
                                    f.field("createdTime").order(SortOrder.Asc)
                                }
                            }.apply {
                                searchAfter?.let { sa -> searchAfter(sa) }
                            }
                    },
                    Dictionary::class.java,
                )

            val hits = response.hits().hits()
            hits.mapNotNull { it.source() }.let { allResults.addAll(it) }

            searchAfter = hits.lastOrNull()?.sort()
        } while (searchAfter != null && response.hits().hits().size == batchSize)

        return allResults
    }

    override fun insert(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        esClient.index {
            it.index(DICTIONARY_INDEX)
            it.document(
                Dictionary.of(
                    keyword = keyword,
                    type = type,
                    value = value,
                    createdTime = Instant.now(),
                    updatedTime = Instant.now(),
                ),
            )
        }
    }

    override fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        esClient.update(
            {
                it
                    .index(DICTIONARY_INDEX)
                    .id(id)
                    .doc(
                        mapOf(
                            "keyword" to keyword,
                            "value" to value,
                            "updatedTime" to Instant.now(),
                        ),
                    )
            },
            Dictionary::class.java,
        )
    }

    override fun delete(id: String) {
        esClient.delete {
            it.index(DICTIONARY_INDEX).id(id)
        }
    }

    private fun baseSortQuery() =
        SortOptions.of {
            it.field { f ->
                f.field("updatedTime")
                f.order(SortOrder.Desc)
            }
            it.field { f2 ->
                f2.field("createdTime")
                f2.order(SortOrder.Desc)
            }
        }

    companion object {
        const val DICTIONARY_INDEX = ".dsearch_dict"
    }
}
